const quotePremium = (items: QuoteItem[]): number => {
  const basePremium = items.reduce(
    (sum, item) => sum + BASE_PREMIUMS[item.type],
    0,
  );
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_RATE;
  return basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioOutput => {
  const quoteStep = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: quotePremium(quoteStep.items) }] };
};
